    // Find the heading "Studio albums"
    const headings = Array.from(document.querySelectorAll('h3'));
    const studioHeading = headings.find(h => h.textContent.includes('Studio albums'));
    if (!studioHeading) return null;
    // Find the next table after this heading
    let nextElem = studioHeading.nextElementSibling;
    while (nextElem && nextElem.tagName !== 'TABLE') {
        nextElem = nextElem.nextElementSibling;
    }
    if (!nextElem) return null;
    const table = nextElem;
    const rows = Array.from(table.querySelectorAll('tr'));
    const data = [];
    rows.forEach(row => {
        const yearCell = row.querySelector('td:nth-child(1)');
        const albumCell = row.querySelector('td:nth-child(2)');
        if (yearCell && albumCell) {
            // Extract text, removing label info after "Label:"
            let albumText = albumCell.textContent.trim();
            // Remove label part if present
            const labelIndex = albumText.indexOf('Label:');
            if (labelIndex !== -1) {
                albumText = albumText.substring(0, labelIndex).trim();
            }
            data.push({
                year: yearCell.textContent.trim(),
                album: albumText
            });
        }
    });
    return data;
}"}

